queue.enqueue(1)
queue.enqueue(2)
queue.enqueue(3)
print(queue.size())  # 3
print(queue.peek())  # 3
print(queue.dequeue())  # 3
print(queue.size())  # 2
print(queue.peek())  # 2
```

